// Keeps source files small: fails when a hand-written file is over the limit.
// Generated, vendored and data files are skipped. Run: npm run check:size
'use strict';
const fs = require('node:fs');
const path = require('node:path');

const MAX_CHARS = 20000;
const ROOT = path.resolve(__dirname, '..');
const EXT = new Set(['.js', '.jsx', '.cjs', '.css', '.html', '.md']);
const SKIP_DIRS = new Set(['node_modules', 'dist', 'var', '.git', 'data']);
// Generated by the design-system tooling, or reference material.
const SKIP_FILES = new Set([
  '_ds_bundle.js',
  'design_handoff_bara_website/README.md',
]);

/**
 * Lists every checked file under a directory.
 * @param {string} dir
 * @param {!Array<string>} out
 * @return {!Array<string>}
 */
function walk(dir, out = []) {
  for (const e of fs.readdirSync(dir, {withFileTypes: true})) {
    const p = path.join(dir, e.name);
    const rel = path.relative(ROOT, p);
    if (e.isDirectory()) {
      if (!SKIP_DIRS.has(e.name)) walk(p, out);
    } else if (EXT.has(path.extname(e.name)) && !SKIP_FILES.has(rel)) {
      out.push(rel);
    }
  }
  return out;
}

const over = walk(ROOT)
  .map((f) => [f, fs.readFileSync(path.join(ROOT, f), 'utf8').length])
  .filter(([, n]) => n > MAX_CHARS)
  .sort((a, b) => b[1] - a[1]);

if (over.length) {
  console.error(`✗ ${over.length} file(s) over ${MAX_CHARS} characters:`);
  for (const [f, n] of over) console.error(`  ${f}  ${n}`);
  process.exit(1);
}
console.log(`✓ every source file is under ${MAX_CHARS} characters`);
